   Q("¿Cuánto es 1/4 de 20?", "5", "80", "4", "Se reparte 20 en 4 partes iguales y cada parte vale 5."),
   Q("{F} ¿Cuántos sacos son 1/3 de los que lleva el camión?", "8", "72", "3", "Se reparten 24 sacos en 3 partes iguales y cada parte tiene 8."),
